/* ---------- App logic ---------- */
const $ = s => document.querySelector(s);
const esc = t => String(t).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const state = { q:'', div:'', gender:'', res:'', cls:'', key:'roll', dir:1 };
const PRAC = new Set(['PHY','CHEM','BIO']);
const titleCase = s => s.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());

// Fill division dropdown
[...new Set(DATA.map(s => s.div))].sort().forEach(d => {
  $('#div').insertAdjacentHTML('beforeend', `<option>${esc(d)}</option>`);
});

function filtered() {
  const q = state.q.trim().toLowerCase();
  return DATA.filter(s =>
    (!q || s.name.toLowerCase().includes(q) || String(s.roll) === q || s.id.includes(q) || s.gr.includes(q)) &&
    (!state.div || s.div === state.div) &&
    (!state.gender || s.g === state.gender) &&
    (!state.res || s.res === state.res) &&
    (!state.cls || s.cls === state.cls)
  ).sort((a, b) => {
    const x = a[state.key], y = b[state.key];
    return (typeof x === 'number' ? x - y : String(x).localeCompare(String(y))) * state.dir || a.roll - b.roll;
  });
}

function bar(label, pct, right) {
  return `<div class="bar"><div class="l"><span>${esc(label)}</span><span>${right}</span></div>
    <div class="t"><div class="f" style="width:${Math.min(100, pct)}%"></div></div></div>`;
}

function render() {
  const list = filtered(), n = list.length;
  const cnt = r => list.filter(s => s.res === r).length;
  const pass = cnt('PASS'), prom = cnt('PROMOTED'), fail = cnt('FAIL');
  const avg = n ? list.reduce((a, s) => a + s.pct, 0) / n : 0;
  const dist = list.filter(s => s.cls === 'I WITH DISTINCTION').length;

  $('#stats').innerHTML = [
    [n, 'Students'], [pass, 'Passed'], [prom, 'Promoted'], [fail, 'Failed'],
    [dist, 'Distinction'], [n ? (pass / n * 100).toFixed(1) + '%' : '–', 'Pass rate'],
    [avg.toFixed(1) + '%', 'Average']
  ].map(([v, l]) => `<div class="stat"><b>${v}</b><span>${l}</span></div>`).join('');

  $('#count').textContent = `${n} of ${DATA.length} students`;
  $('#rows').innerHTML = n ? list.map(s => `
    <tr data-id="${s.id}">
      <td>${s.roll}</td><td class="name">${esc(s.name)}</td><td>${s.div}</td>
      <td class="num">${s.tot}</td><td class="num">${s.pct.toFixed(2)}</td>
      <td><span class="chip ${s.res}">${s.res}</span></td><td>${esc(titleCase(s.cls))}</td>
    </tr>`).join('') : `<tr><td colspan="7" class="empty">No students match these filters.</td></tr>`;

  document.querySelectorAll('th').forEach(th => {
    const on = th.dataset.k === state.key;
    th.classList.toggle('sorted', on);
    th.dataset.arrow = on ? (state.dir > 0 ? '▲' : '▼') : '';
  });

  // Division comparison (pass rate within current filter)
  const divs = [...new Set(list.map(s => s.div))].sort();
  $('#divs').innerHTML = divs.map(d => {
    const g = list.filter(s => s.div === d), p = g.filter(s => s.res === 'PASS').length;
    return bar(`Div ${d} (${g.length})`, p / g.length * 100, `${(p / g.length * 100).toFixed(0)}% pass`);
  }).join('') || '<p class="empty">No data</p>';

  // Subject averages (% of max marks)
  const m = {};
  list.forEach(s => s.subs.forEach(x => {
    const pct = ['HPE', 'EVS'].includes(x[0]) ? x[7] * 2 : x[9];
    (m[x[0]] ||= { n: x[1], sum: 0, c: 0 });
    m[x[0]].sum += pct; m[x[0]].c++;
  }));
  $('#subj').innerHTML = Object.entries(m).map(([c, o]) =>
    bar(titleCase(o.n), o.sum / o.c, (o.sum / o.c).toFixed(1) + '%')).join('') || '<p class="empty">No data</p>';

  $('#top').innerHTML = [...list].sort((a, b) => b.tot - a.tot).slice(0, 5).map(s =>
    `<li data-id="${s.id}">${esc(titleCase(s.name))} <small>· ${s.div} · ${s.tot}/600 (${s.pct.toFixed(1)}%)</small></li>`).join('');
}

function openStudent(id) {
  const s = DATA.find(x => x.id === id); if (!s) return;
  $('#dname').textContent = titleCase(s.name);
  const cell = v => v === null ? 'AB' : v;
  const rows = s.subs.map(x => {
    if (['HPE', 'EVS'].includes(x[0]))
      return `<tr><td>${esc(titleCase(x[1]))}</td><td colspan="5" class="mute">Graded subject</td><td class="num">${x[7]}/50</td><td></td><td class="num">A</td></tr>`;
    return `<tr><td>${esc(titleCase(x[1]))}</td><td class="num">${cell(x[2])}</td><td class="num">${cell(x[3])}</td>
      <td class="num">${cell(x[4])}</td><td class="num">${cell(x[5])}</td><td class="num">${cell(x[6])}</td>
      <td class="num">${x[7]}</td><td class="num">${x[8] || ''}</td><td class="num"><b>${x[9]}</b></td></tr>`;
  }).join('');
  $('#dbody').innerHTML = `
    <div class="meta">
      <span>Roll <b>${s.roll}</b></span><span>Division <b>${s.div}</b></span>
      <span>${titleCase(s.g)}</span><span>DOB <b>${s.dob}</b></span>
      <span>Student ID <b>${s.id}</b></span><span>GR No <b>${s.gr}</b></span>
    </div>
    <div class="meta">
      <span>Total <b>${s.tots.replace('/600', '')} / 600</b></span><span><b>${s.pct.toFixed(2)}%</b></span>
      <span class="chip ${s.res}">${s.res}</span>${s.cls ? `<span><b>${esc(titleCase(s.cls))}</b></span>` : ''}
    </div>
    <div class="scroll"><table>
      <thead><tr><th>Subject</th><th class="num">Unit 1</th><th class="num">Term 1</th><th class="num">Unit 2</th>
      <th class="num">Oral / Prac.</th><th class="num">Term 2</th><th class="num">Total</th><th class="num">Grace</th><th class="num">Avg (/2)</th></tr></thead>
      <tbody>${rows}</tbody></table></div>`;
  $('#dlg').showModal();
}

function exportCSV() {
  const head = ['Roll', 'Student ID', 'GR No', 'Name', 'Gender', 'Division', 'Total', 'Percent', 'Result', 'Class'];
  const q = v => `"${String(v).replace(/"/g, '""')}"`;
  const lines = [head.join(',')].concat(filtered().map(s =>
    [s.roll, s.id, s.gr, s.name, s.g, s.div, s.tot, s.pct, s.res, s.cls].map(q).join(',')));
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([lines.join('\n')], { type: 'text/csv' }));
  a.download = 'xi-science-results.csv'; a.click(); URL.revokeObjectURL(a.href);
}

// Events
$('#q').addEventListener('input', e => { state.q = e.target.value; render(); });
[['#div', 'div'], ['#gender', 'gender'], ['#res', 'res'], ['#cls', 'cls']].forEach(([sel, k]) =>
  $(sel).addEventListener('change', e => { state[k] = e.target.value; render(); }));
document.querySelectorAll('th[data-k]').forEach(th => th.addEventListener('click', () => {
  const k = th.dataset.k;
  state.dir = state.key === k ? -state.dir : 1; state.key = k; render();
}));
document.addEventListener('click', e => {
  const r = e.target.closest('tr[data-id], li[data-id]');
  if (r) openStudent(r.dataset.id);
});
$('#close').addEventListener('click', () => $('#dlg').close());
$('#dlg').addEventListener('click', e => { if (e.target.id === 'dlg') e.target.close(); });
$('#csv').addEventListener('click', exportCSV);

render();
